//! Sources-list-only color metadata and one bounded custom row preview.
use eframe::egui;use skylive_core::{Id,Session,StudioSnapshot,SourceItemColorTag as Tag,SourceItemColorPreset as Preset};
use std::sync::atomic::{AtomicU64,Ordering};
const FOCUS:&str="source-row-color-focus";const PREVIEW:&str="source-row-color-preview";static NEXT:AtomicU64=AtomicU64::new(1);
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Scope{pub session:u64,pub revision:u64,pub root:Id,pub container:Id,pub item:Id,pub source:Id,pub before:Tag}
impl Scope{pub fn current(self,session:u64,model:&StudioSnapshot,root:Id,selected:Option<Id>)->bool{session==self.session&&model.revision()==self.revision&&root==self.root&&selected==Some(self.item)&&model.root_scene_for_container(self.container)==Some(root)&&model.item_container(self.item).is_some_and(|(owner,item)|owner==self.container&&item.source()==self.source&&item.color_tag()==self.before)}}
#[derive(Clone,Copy)]struct Focus{session:u64,revision:u64,root:Id,selected:Option<Id>,token:Option<u64>}
#[derive(Clone,Copy)]struct Preview{scope:Scope,token:u64,rgba:[u8;4]}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Draft{pub scope:Scope,pub token:u64,pub rgba:[u8;4]}
impl Draft{fn new(scope:Scope)->Result<Self,String>{let token=NEXT.fetch_update(Ordering::Relaxed,Ordering::Relaxed,|old|old.checked_add(1)).map_err(|_|"Source color draft identity exhausted.")?;Ok(Self{scope,token,rgba:scope.before.custom_initial()})}pub fn action(self)->Action{Action::Apply{scope:self.scope,token:self.token,rgba:self.rgba}}}
#[derive(Clone,Copy)]pub enum Action{Set{scope:Scope,tag:Tag},Apply{scope:Scope,token:u64,rgba:[u8;4]}}
pub fn install(ctx:&egui::Context,session:&Session,root:Id,selected:Option<Id>,dialog:Option<&super::dialogs::Dialog>){let token=match dialog{Some(super::dialogs::Dialog::SourceColorTag(draft))=>Some(draft.token),_=>None};ctx.data_mut(|data|{data.insert_temp(egui::Id::new(FOCUS),Focus{session:session.identity(),revision:session.snapshot().revision(),root,selected,token});data.remove::<Preview>(egui::Id::new(PREVIEW));});if let Some(super::dialogs::Dialog::SourceColorTag(draft))=dialog{publish_preview(ctx,&session.snapshot(),draft);}}
fn focus(ctx:&egui::Context)->Option<Focus>{ctx.data(|data|data.get_temp(egui::Id::new(FOCUS)))}
pub fn fresh(ctx:&egui::Context,model:&StudioSnapshot,draft:&Draft)->bool{focus(ctx).is_some_and(|f|f.revision==model.revision()&&f.token==Some(draft.token)&&draft.scope.current(f.session,model,f.root,f.selected))}
fn publish_preview(ctx:&egui::Context,model:&StudioSnapshot,draft:&Draft){if fresh(ctx,model,draft){ctx.data_mut(|data|data.insert_temp(egui::Id::new(PREVIEW),Preview{scope:draft.scope,token:draft.token,rgba:draft.rgba}));}else{clear(ctx,draft.token);}}
pub fn clear_all(ctx:&egui::Context){ctx.data_mut(|data|data.remove::<Preview>(egui::Id::new(PREVIEW)));ctx.request_repaint();}
pub fn clear(ctx:&egui::Context,token:u64){ctx.data_mut(|data|{if data.get_temp::<Preview>(egui::Id::new(PREVIEW)).is_some_and(|preview|preview.token==token){data.remove::<Preview>(egui::Id::new(PREVIEW));}});ctx.request_repaint();}
pub fn effective(ctx:&egui::Context,model:&StudioSnapshot,session:u64,container:Id,item:Id,tag:Tag)->Tag{let preview=ctx.data(|data|data.get_temp::<Preview>(egui::Id::new(PREVIEW)));if let(Some(preview),Some(f))=(preview,focus(ctx)){if f.token==Some(preview.token)&&preview.scope.container==container&&preview.scope.item==item&&preview.scope.current(session,model,f.root,f.selected){return Tag::Custom{rgba:preview.rgba};}}tag}
pub fn menu(ui:&mut egui::Ui,model:&StudioSnapshot,container:Id,item:Id,session:u64,intents:&mut Vec<super::Intent>){
 let Some((owner,entry))=model.item_container(item).filter(|(owner,_)|*owner==container)else{return;};let Some(f)=focus(ui.ctx())else{return;};let scope=Scope{session,revision:model.revision(),root:f.root,container:owner,item,source:entry.source(),before:entry.color_tag()};let available=scope.current(f.session,model,f.root,f.selected);
 ui.add_enabled_ui(available,|ui|{ui.menu_button(crate::i18n::tr_key_or(ui,"ChangeBG","Set Color"),|ui|{
  ui.label(crate::i18n::tr(ui,"Color applies only to this selected source item row."));
  if ui.radio(scope.before.is_clear(),crate::i18n::tr_key_or(ui,"Clear","Clear")).on_hover_text(crate::i18n::tr(ui,"Remove the row color without changing source pixels or audio.")).clicked(){intents.push(super::Intent::SourceColorTag(Action::Set{scope,tag:Tag::Clear}));ui.close_menu();}
  if ui.radio(matches!(scope.before,Tag::Custom{..}),crate::i18n::tr_key_or(ui,"CustomColor","Custom Color")).on_hover_text(crate::i18n::tr(ui,"Preview a custom RGBA row color. Apply commits it; Cancel restores the previous row color.")).clicked(){match Draft::new(scope){Ok(draft)=>intents.push(super::Intent::OpenDialog(super::dialogs::Dialog::SourceColorTag(draft))),Err(error)=>intents.push(super::Intent::DialogError(error))}ui.close_menu();}
  ui.separator();egui::Grid::new(("source-color-presets",item.get())).num_columns(2).show(ui,|ui|{for(index,preset)in Preset::ALL.into_iter().enumerate(){ui.horizontal(|ui|{let(rect,_)=ui.allocate_exact_size(egui::vec2(14.0,14.0),egui::Sense::hover());let [r,g,b,a]=preset.rgba();ui.painter().rect_filled(rect,2.0,egui::Color32::from_rgba_unmultiplied(r,g,b,a));if ui.radio(scope.before==(Tag::Preset{preset}),crate::i18n::tr(ui,preset.label())).on_hover_text(crate::i18n::tr(ui,"Use this OBS row-color preset at 33% opacity.")).clicked(){intents.push(super::Intent::SourceColorTag(Action::Set{scope,tag:Tag::Preset{preset}}));ui.close_menu();}});if index%2==1{ui.end_row();}}});
 }).response.on_hover_text(crate::i18n::tr(ui,"Set a Sources-list color for this item, independently of other references to the same source."));}).response.on_disabled_hover_text(crate::i18n::tr(ui,"Select this source item before changing its row color."));
}
pub fn editor(ui:&mut egui::Ui,model:&StudioSnapshot,draft:&mut Draft){
 let valid=fresh(ui.ctx(),model,draft);if !valid{ui.colored_label(ui.visuals().error_fg_color,crate::i18n::tr(ui,"This source color draft is obsolete. Cancel and reopen Set Color."));}
 if let Some(source)=model.source(draft.scope.source){ui.label(crate::i18n::tf(ui,"Selected item: {name}",&[("{name}",source.name().into())]));}
 ui.label(crate::i18n::tr(ui,"This previews the current Sources row only. Source pixels, filters and audio are unchanged."));
 ui.add_enabled_ui(valid,|ui|{let mut chosen=draft.rgba;let picker=ui.color_edit_button_srgba_unmultiplied(&mut chosen).on_hover_text(crate::i18n::tr(ui,"Choose red, green, blue and alpha for the row background."));if picker.changed(){if chosen[3]==0{chosen[..3].copy_from_slice(&draft.rgba[..3]);}draft.rgba=chosen;}
 // egui's linear-premultiplied picker adapter roundtrips every frame. Commit
 // only real edits; never erase authored zero-alpha RGB or quantize on hover.
 egui::Grid::new("source-color-rgba").num_columns(2).show(ui,|ui|{for(index,label)in ["Red","Green","Blue","Alpha"].into_iter().enumerate(){let name=ui.label(crate::i18n::tr(ui,label));ui.add(egui::DragValue::new(&mut draft.rgba[index]).range(0..=255)).labelled_by(name.id).on_hover_text(crate::i18n::tr(ui,"Channel value from 0 to 255; alpha controls row-color opacity."));ui.end_row();}});let[r,g,b,a]=draft.rgba;ui.monospace(format!("#{a:02x}{r:02x}{g:02x}{b:02x}"));if ui.button(crate::i18n::tr(ui,"Use default custom color")).on_hover_text(crate::i18n::tr(ui,"Use the OBS custom picker fallback #55FF0000 in this draft.")).clicked(){draft.rgba=[255,0,0,85];}});
 publish_preview(ui.ctx(),model,draft);
}
pub fn tooltip(ui:&egui::Ui,name:&str,tag:Tag)->String{let color=match tag{Tag::Custom{rgba:[r,g,b,a]}=>format!("{} #{a:02x}{r:02x}{g:02x}{b:02x}",crate::i18n::tr(ui,"Custom Color")),_=>crate::i18n::tr(ui,tag.label())};crate::i18n::tf(ui,"{name}\nRow color: {color}",&[("{name}",name.into()),("{color}",color)])}
/// Theme-aware foreground/controls over the composited tint; selection remains
/// a semantic selected button plus a contrasting full-row outline.
pub fn row_fill(ui:&egui::Ui,rgba:[u8;4])->egui::Color32{let faint=ui.visuals().faint_bg_color;let window=ui.visuals().window_fill;let coverage=f32::from(faint.a())/255.0;let underlying=|f:u8,w:u8|(f32::from(f)+f32::from(w)*(1.0-coverage)).min(255.0);let alpha=f32::from(rgba[3])/255.0;let blend=|i:usize,f:u8,w:u8|(f32::from(rgba[i])*alpha+underlying(f,w)*(1.0-alpha)).round()as u8;egui::Color32::from_rgb(blend(0,faint.r(),window.r()),blend(1,faint.g(),window.g()),blend(2,faint.b(),window.b()))}
pub fn row_style(ui:&mut egui::Ui,rgba:[u8;4])->egui::Color32{let bg=row_fill(ui,rgba);let linear=|v:u8|{let s=f32::from(v)/255.0;if s<=0.04045{s/12.92}else{((s+0.055)/1.055).powf(2.4)}};let luminance=0.2126*linear(bg.r())+0.7152*linear(bg.g())+0.0722*linear(bg.b());let fg=if luminance>0.179{egui::Color32::BLACK}else{egui::Color32::WHITE};let visual=ui.visuals_mut();visual.override_text_color=Some(fg);visual.selection.bg_fill=egui::Color32::TRANSPARENT;visual.selection.stroke.color=fg;for widget in [&mut visual.widgets.noninteractive,&mut visual.widgets.inactive,&mut visual.widgets.hovered,&mut visual.widgets.active,&mut visual.widgets.open]{widget.fg_stroke.color=fg;widget.bg_fill=bg;widget.weak_bg_fill=bg;}fg}
